-- Krok 1 na PROD: kontrola wstępna (musi przejść bez błędu). Nic nie zapisuje.
DO $$
DECLARE missing text;
BEGIN
  SELECT string_agg(r.t || '.' || r.c, ', ') INTO missing
  FROM (VALUES ('users', 'id'), ('users', 'name'), ('users', 'email'), ('users', 'emailVerified'), ('users', 'image'), ('users', 'role'), ('users', 'created_at'), ('users', 'updated_at'), ('users', 'deleted_at'), ('users', 'phone'), ('users', 'blocked_at'), ('users', 'blocked_by'), ('users', 'blocked_reason'), ('producer', 'id'), ('producer', 'user_id'), ('producer', 'nip'), ('producer', 'name'), ('producer', 'country_code'), ('producer', 'rating'), ('producer', 'review_count'), ('producer', 'technology'), ('producer', 'verification_status'), ('producer', 'created_at'), ('producer', 'updated_at'), ('producer', 'deleted_at'), ('producer', 'production_scale'), ('producer', 'inquiry_response_time_label'), ('producer', 'showroom_visit_available'), ('producer', 'showroom_visit_note'), ('producer', 'description'), ('producer_delivery_country', 'producer_id'), ('producer_delivery_country', 'country_code'), ('producer_delivery_country', 'created_at'), ('producer_member', 'id'), ('producer_member', 'producer_id'), ('producer_member', 'user_id'), ('producer_member', 'added_by'), ('producer_member', 'created_at'), ('producer_translation', 'id'), ('producer_translation', 'producer_id'), ('producer_translation', 'locale'), ('producer_translation', 'description'), ('producer_translation', 'showroom_visit_note'), ('producer_translation', 'inquiry_response_time_label'), ('producer_translation', 'created_at'), ('producer_translation', 'updated_at'), ('reference_text_translation', 'id'), ('reference_text_translation', 'source_pl'), ('reference_text_translation', 'locale'), ('reference_text_translation', 'translated'), ('reference_text_translation', 'created_at'), ('reference_text_translation', 'updated_at'), ('product', 'id'), ('product', 'producer_id'), ('product', 'status'), ('product', 'name'), ('product', 'country_of_production'), ('product', 'floor_area_m2'), ('product', 'built_up_area_m2'), ('product', 'description'), ('product', 'completion_standard'), ('product', 'production_lead_time_weeks_min'), ('product', 'production_lead_time_weeks_max'), ('product', 'on_site_assembly_days_min'), ('product', 'on_site_assembly_days_max'), ('product', 'house_price_min_cents'), ('product', 'house_price_max_cents'), ('product', 'structural_warranty_years'), ('product', 'category'), ('product', 'rooms'), ('product', 'bedrooms'), ('product', 'bathrooms'), ('product', 'storeys'), ('product', 'external_dimensions'), ('product', 'roof_type'), ('product', 'construction_system'), ('product', 'foundation_options'), ('product', 'customization_scope'), ('product', 'currency'), ('product', 'price_includes'), ('product', 'price_excludes'), ('product', 'featured'), ('product', 'created_at'), ('product', 'updated_at'), ('product', 'deleted_at'), ('product', 'family'), ('product', 'spa_subcategory'), ('product', 'technical_specs'), ('product', 'cover_image_url'), ('product', 'container_subcategory'), ('product', 'installation_warranty_years'), ('product', 'service_scope_description'), ('product', 'transport_dimensions'), ('product', 'crane_requirements'), ('product', 'min_plot_width_m'), ('product', 'room_layout'), ('product', 'faq'), ('product', 'simplified_permit_eligible'), ('product', 'client_requirements'), ('product', 'video_url'), ('product', 'slug'), ('product_translation', 'id'), ('product_translation', 'product_id'), ('product_translation', 'locale'), ('product_translation', 'name'), ('product_translation', 'description'), ('product_translation', 'created_at'), ('product_translation', 'updated_at'), ('product_translation', 'room_layout'), ('product_translation', 'faq'), ('product_translation', 'ai_generated_name'), ('product_translation', 'ai_generated_description'), ('product_translation', 'ai_translated_from_name'), ('product_translation', 'ai_translated_from_description'), ('product_translation', 'client_requirements'), ('product_translation', 'foundation_options'), ('product_translation', 'technical_specs'), ('product_translation', 'construction_system'), ('product_translation', 'roof_type'), ('product_translation', 'customization_scope'), ('product_translation', 'service_scope_description'), ('product_country_eligibility', 'product_id'), ('product_country_eligibility', 'country_code'), ('product_country_eligibility', 'status'), ('product_country_eligibility', 'reason'), ('product_country_eligibility', 'created_at'), ('product_country_eligibility', 'updated_at'), ('document', 'id'), ('document', 'r2_key'), ('document', 'filename'), ('document', 'mime_type'), ('document', 'size_bytes'), ('document', 'purpose'), ('document', 'is_cover'), ('document', 'sort_order'), ('document', 'owner_user_id'), ('document', 'product_id'), ('document', 'order_stage_event_id'), ('document', 'producer_id'), ('document', 'created_at'), ('document', 'deleted_at'), ('document', 'product_variant_id'), ('document', 'project_quote_id'), ('document', 'product_option_id'), ('document', 'floor_level')) AS r(t, c)
  WHERE NOT EXISTS (
    SELECT 1 FROM information_schema.columns k
    WHERE k.table_schema = 'public' AND k.table_name = r.t AND k.column_name = r.c
  );
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'Na tej bazie brakuje kolumn (najpierw wdróż wcześniejsze migracje): %', missing;
  END IF;
END $$;
